import{_ as m,a0 as n,w as s,s as p,I as t,x as o,a1 as l,A as d,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用以檢查 Linux 內存使用的 5 個命令 | LCTT x X-CMD","titleTemplate":false,"description":"用以檢查 Linux 內存使用的 5 個命令 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用以檢查 Linux 內存使用的 5 個命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用以檢查 Linux 內存使用的 5 個命令 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180615 5 Commands for Checking Memory Usage in Linux","title":"用以檢查 Linux 內存使用的 5 個命令","tag":"201808","desc":""},"relativePath":"201808/20180615 5 Commands for Checking Memory Usage in Linux.md","filePath":"[post].md"}'),a={name:"201808/20180615 5 Commands for Checking Memory Usage in Linux.md"};function u(c,e,f,x,w,g){const i=n("Link");return s(),p("div",null,[e[24]||(e[24]=t("h1",{id:"用以檢查-linux-內存使用的-5-個命令",tabindex:"-1"},[o("用以檢查 Linux 內存使用的 5 個命令 "),t("a",{class:"header-anchor",href:"#用以檢查-linux-內存使用的-5-個命令","aria-label":"Permalink to “用以檢查 Linux 內存使用的 5 個命令”"},"​")],-1)),e[25]||(e[25]=t("blockquote",null,[t("p",null,"對於 Linux 管理員來説，檢查系統內存用量是一個重要的技能。Jack 給出瞭解決這個問題的五種不同方式。")],-1)),e[26]||(e[26]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/top-main.jpg?itok=WYAw6yJ1",alt:""})],-1)),e[27]||(e[27]=t("p",null,"Linux 操作系統包含大量工具，所有這些工具都可以幫助你管理系統。從簡單的文件和目錄工具到非常複雜的安全命令，在 Linux 中沒有多少是你做不了的。而且，儘管普通桌面用户可能不需要在命令列熟悉這些工具，但對於 Linux 管理員來説，它們是必需的。為什麼？首先，你在某些時候不得不使用沒有 GUI 的 Linux 服務器。其次，命令列工具通常比 GUI 替代工具提供更多的功能和靈活性。",-1)),e[28]||(e[28]=t("p",null,"確定內存使用情況是你可能需要的技能，尤其是某個應用程序變得異常和佔用系統內存時。當發生這種情況時，知道有多種工具可以幫助你進行故障排除十分方便的。或者，你可能需要收集有關 Linux 交換分區的信息，或者有關安裝的內存的詳細信息？對於這些也有相應的命令。讓我們深入瞭解各種 Linux 命令列工具，以幫助你檢查系統內存使用情況。這些工具並不是非常難以使用，在本文中，我將向你展示五種不同的方法來解決這個問題。",-1)),t("p",null,[e[1]||(e[1]=o("我將在 ",-1)),l(i,{href:"https://www.ubuntu.com/download/server"},{default:d(()=>[...e[0]||(e[0]=[o("Ubuntu 18.04 服務器平台",-1)])]),_:1}),e[2]||(e[2]=o("上進行演示，但是你應該在你選擇的發行版中找到對應的所有命令。更妙的是，你不需要安裝任何東西（因為大多數這些工具都包含 Linux 系統中）。",-1))]),e[29]||(e[29]=t("p",null,"話雖如此，讓我們開始工作吧。",-1)),e[30]||(e[30]=t("h3",{id:"top",tabindex:"-1"},[o("top "),t("a",{class:"header-anchor",href:"#top","aria-label":"Permalink to “top”"},"​")],-1)),e[31]||(e[31]=t("p",null,[o("我想從最常用的工具開始。"),t("code",null,"top"),o(" 命令提供正在運行的系統的實時動態視圖，它檢查每個進程的內存使用情況。這非常重要，因為你可以輕鬆地看到同一命令的多個示例消耗不同的內存量。雖然你無法在沒有顯示器的服務器上看到這種情況，但是你已經注意到打開 Chrome 使你的系統速度變慢了。運行 "),t("code",null,"top"),o(" 命令以查看 Chrome 有多個進程在運行（每個選項卡一個 - 圖 1）。")],-1)),e[32]||(e[32]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_1.jpg?itok=fhhhUL_l",alt:"top",title:"top"})],-1)),e[33]||(e[33]=t("p",null,[t("em",null,"圖1：top 命令中出現多個 Chrome 進程。")],-1)),t("p",null,[e[4]||(e[4]=o("Chrome 並不是唯一顯示多個進程的應用。你看到圖 1 中的 Firefox 了嗎？那是 Firefox 的主進程，而 Web Content 進程是其打開的選項卡。在輸出的頂部，你將看到系統統計信息。在我的機器上（",-1)),l(i,{href:"https://system76.com/desktops/leopard"},{default:d(()=>[...e[3]||(e[3]=[o("System76 Leopard Extreme",-1)])]),_:1}),e[5]||(e[5]=o("），我總共有 16GB 可用 RAM，其中只有超過 10GB 的 RAM 正在使用中。然後，你可以整理該列表，查看每個進程使用的內存百分比。",-1))]),e[34]||(e[34]=r('<p><code>top</code> 最好的地方之一就是發現可能已經失控的服務的進程 ID 號（PID）。有了這些 PID，你可以對有問題的任務進行故障排除（或 <code>kill</code>）。</p><p>如果你想讓 <code>top</code> 顯示更友好的內存信息，使用命令 <code>top -o ％MEM</code>，這會使 <code>top</code> 按進程所用內存對所有進程進行排序（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_2.jpg?itok=zuVkQfvv" alt="top" title="top"></p><p><em>圖 2：在 top 命令中按使用內存對進程排序</em></p><p><code>top</code> 命令還為你提供有關使用了多少交換空間的實時更新。</p><h3 id="free" tabindex="-1">free <a class="header-anchor" href="#free" aria-label="Permalink to “free”">​</a></h3><p>然而有時候，<code>top</code> 命令可能不能滿足你的需求。你可能只需要查看系統的可用和已用內存。對此，Linux 還有 <code>free</code> 命令。<code>free</code> 命令顯示：</p><ul><li>可用和已使用的物理內存總量</li><li>系統中交換內存的總量</li><li>內核使用的緩衝區和緩存</li></ul><p>在終端窗口中，輸入 <code>free</code> 命令。它的輸出不是實時的，相反，你將獲得的是當前空閒和已用內存的即時快照（圖 3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_3.jpg?itok=rvuQp3t0" alt="free" title="free"></p><p><em>圖 3 ：free 命令的輸出簡單明瞭。</em></p><p>當然，你可以通過添加 <code>-m</code> 選項來讓 <code>free</code> 顯示得更友好一點，就像這樣：<code>free -m</code>。這將顯示內存的使用情況，以 MB 為單位（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_4.jpg?itok=K_luLLPt" alt="free" title="free"></p><p><em>圖 4：free 命令以一種更易於閲讀的形式輸出。</em></p><p>當然，如果你的系統是很新的，你將希望使用 <code>-g</code> 選項（以 GB 為單位），比如 <code>free -g</code>。</p><p>如果你需要知道內存總量，你可以添加 <code>-t</code> 選項，比如：<code>free -mt</code>。這將簡單地計算每列中的內存總量（圖 5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_5.jpg?itok=q50atcsX" alt="total" title="total"></p><p><em>圖 5：為你提供空閒的內存列。</em></p><h3 id="vmstat" tabindex="-1">vmstat <a class="header-anchor" href="#vmstat" aria-label="Permalink to “vmstat”">​</a></h3><p>另一個非常方便的工具是 <code>vmstat</code>。這個特殊的命令是一個報告虛擬內存統計信息的小技巧。<code>vmstat</code> 命令將報告關於：</p><ul><li>進程</li><li>內存</li><li>分頁</li><li>阻塞 IO</li><li>中斷</li><li>磁盤</li><li>CPU</li></ul><p>使用 <code>vmstat</code> 的最佳方法是使用 <code>-s</code> 選項，如 <code>vmstat -s</code>。這將在單列中報告統計信息（這比默認報告更容易閲讀）。<code>vmstat</code> 命令將提供比你需要的更多的信息（圖 6），但更多的總是更好的（在這種情況下）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_6.jpg?itok=bwFnUVmy" alt="vmstat" title="vmstat"></p><p><em>圖 6：使用 vmstat 命令來檢查內存使用情況。</em></p><h3 id="dmidecode" tabindex="-1">dmidecode <a class="header-anchor" href="#dmidecode" aria-label="Permalink to “dmidecode”">​</a></h3><p>如果你想找到關於已安裝的系統內存的詳細信息，該怎麼辦？為此，你可以使用 <code>dmidecode</code> 命令。這個特殊的工具是 DMI 表解碼器，它將系統的 DMI 表內容轉儲成人類可讀的格式。如果你不清楚 DMI 表是什麼，那麼可以這樣説，它可以用來描述系統的構成（以及系統的演變）。</p><p>要運行 <code>dmidecode</code> 命令，你需要 <code>sudo</code> 權限。因此輸入命令 <code>sudo dmidecode -t 17</code>。該命令的輸出（圖 7）可能很長，因為它顯示所有內存類型設備的信息。因此，如果你無法上下滾動，則可能需要將該命令的輸出發送到一個文件中，比如：<code>sudo dmidecode -t 17&gt; dmi_infoI</code>，或將其傳遞給 <code>less</code> 命令，如 <code>sudo dmidecode | less</code>。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_7.jpg?itok=UNHIT_P6" alt="dmidecode" title="dmidecode"></p><p><em>圖 7：dmidecode 命令的輸出。</em></p><h3 id="proc-meminfo" tabindex="-1">/proc/meminfo <a class="header-anchor" href="#proc-meminfo" aria-label="Permalink to “/proc/meminfo”">​</a></h3><p>你可能會問自己：“這些命令從哪裏獲取這些信息？”在某些情況下，它們從 <code>/proc/meminfo</code> 文件中獲取。猜到了嗎？你可以使用命令 <code>less /proc/meminfo</code> 直接讀取該文件。通過使用 <code>less</code> 命令，你可以在長長的輸出中向上和向下滾動，以準確找到你需要的內容（圖 8）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_8.jpg?itok=t87jvmJJ" alt="/proc/meminfo" title="/proc/meminfo"></p><p><em>圖 8：less /proc/meminfo 命令的輸出。</em></p><p>關於 <code>/proc/meminfo</code> 你應該知道：這不是一個真實的文件。相反 <code>/proc/meminfo</code> 是一個虛擬文件，包含有關係統的實時動態信息。特別是，你需要檢查以下值：</p><ul><li>全部內存（<code>MemTotal</code>）</li><li>空閒內存（<code>MemFree</code>）</li><li>可用內存（<code>MemAvailable</code>）</li><li>緩衝區（<code>Buffers</code>）</li><li>文件緩存（<code>Cached</code>）</li><li>交換緩存（<code>SwapCached</code>）</li><li>全部交換區（<code>SwapTotal</code>）</li><li>空閒交換區（<code>SwapFree</code>）</li></ul><p>如果你想使用 <code>/proc/meminfo</code>，你可以連接 egrep 命令使用它：<code>egrep --color&#39;Mem | Cache | Swap&#39;/proc/meminfo</code>。這將生成一個易於閲讀的列表，其中包含 <code>Mem</code>、 <code>Cache</code> 和 <code>Swap</code> 等內容的條目將是彩色的（圖 9）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/memory_9.jpg?itok=t-iSMEKq" alt="/proc/meminfo" title="/proc/meminfo"></p><p><em>圖 9：讓 /proc/meminfo 更容易閲讀。</em></p><h3 id="繼續學習" tabindex="-1">繼續學習 <a class="header-anchor" href="#繼續學習" aria-label="Permalink to “繼續學習”">​</a></h3><p>你要做的第一件事就是閲讀每個命令的手冊頁（例如 <code>man top</code>、<code>man free</code>、<code>man vmstat</code>、<code>man dmidecode</code>）。從命令的手冊頁開始，對於如何在 Linux 上使用一個工具，它總是一個很好的學習方法。</p>',40)),t("p",null,[e[7]||(e[7]=o("通過 Linux 基金會和 edX 的免費 ",-1)),l(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:d(()=>[...e[6]||(e[6]=[o("“Linux 簡介”",-1)])]),_:1}),e[8]||(e[8]=o("課程瞭解有關 Linux 的更多知識。",-1))]),e[35]||(e[35]=t("hr",null,null,-1)),t("p",null,[e[10]||(e[10]=o("via: ",-1)),l(i,{href:"https://www.linux.com/learn/5-commands-checking-memory-usage-linux"},{default:d(()=>[...e[9]||(e[9]=[o("https://www.linux.com/learn/5-commands-checking-memory-usage-linux",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=o("作者：",-1)),l(i,{href:"https://www.linux.com/users/jlwallen"},{default:d(()=>[...e[11]||(e[11]=[o("Jack Wallen",-1)])]),_:1}),e[16]||(e[16]=o(" 選題：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[12]||(e[12]=[o("lujun9972",-1)])]),_:1}),e[17]||(e[17]=o(" 譯者：",-1)),l(i,{href:"https://github.com/MjSeven"},{default:d(()=>[...e[13]||(e[13]=[o("MjSeven",-1)])]),_:1}),e[18]||(e[18]=o(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=o("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[19]||(e[19]=[o("LCTT",-1)])]),_:1}),e[22]||(e[22]=o(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:d(()=>[...e[20]||(e[20]=[o("Linux中國",-1)])]),_:1}),e[23]||(e[23]=o(" 榮譽推出",-1))])])}const k=m(a,[["render",u]]);export{C as __pageData,k as default};
